static TestProc init_repo(const char *repo){const char *a[]={"./darc","init",repo,NULL};return test_exec(a,NULL);}
static TestProc snap1(const char *repo,const char *src,const char *cfg,const char *name,const char *parent,const char *ts){const char *a[18];int i=0;a[i++]="./darc";a[i++]="--repo";a[i++]=repo;if(cfg){a[i++]="--config";a[i++]=cfg;}a[i++]="snapshot";a[i++]="create";a[i++]=src;if(name){a[i++]="--name";a[i++]=name;}if(parent){a[i++]="--parent";a[i++]=parent;}if(ts){a[i++]="--timestamp";a[i++]=ts;}a[i]=NULL;return test_exec(a,NULL);}
static int flat(const char *repo,const char *sel,DarcFlatTree *t,DarcSnapshotObj *s,DarcCid *id){int rc=darc_resolve_snapshot(repo,sel,id,s);if(rc)return rc;rc=darc_flatten_snapshot(repo,s,t);if(rc)darc_snapshot_free(s);return rc;}
static char *cfgtext(const char *d,const char *name,const char *text){char *p=test_path(d,name);if(p)test_write(p,text,strlen(text),0644);return p;}
static bool exists_type(const char*p,mode_t t){struct stat s;return !lstat(p,&s)&&(s.st_mode&S_IFMT)==t;}
static void fixed_meta(const char *p){struct stat st;if(lstat(p,&st))return;if(!S_ISLNK(st.st_mode)){struct timespec z[2]={{0,0},{0,0}};(void)utimensat(AT_FDCWD,p,z,0);if(S_ISDIR(st.st_mode)){DIR*d=opendir(p);if(d){struct dirent*e;while((e=readdir(d)))if(strcmp(e->d_name,".")&&strcmp(e->d_name,"..")){char*q=test_path(p,e->d_name);fixed_meta(q);free(q);}closedir(d);}(void)chmod(p,0755);}else (void)chmod(p,0644);}}
static void chmod_rw_tree(const char*p){struct stat st;if(lstat(p,&st))return;if(S_ISDIR(st.st_mode)){chmod(p,0777);DIR*d=opendir(p);if(d){struct dirent*e;while((e=readdir(d)))if(strcmp(e->d_name,".")&&strcmp(e->d_name,"..")){char*q=test_path(p,e->d_name);chmod_rw_tree(q);free(q);}closedir(d);}}else chmod(p,0666);}
static bool head_empty(const char*repo){char h[65];return !test_head(repo,h)&&!h[0];}
static int restore_head(const char*repo,const char*to,const char*path,const char*overwrite){const char*a[14];int i=0;a[i++]="./darc";a[i++]="--repo";a[i++]=repo;a[i++]="restore";a[i++]="HEAD";a[i++]="--to";a[i++]=to;if(path){a[i++]="--path";a[i++]=path;}if(overwrite){a[i++]="--overwrite";a[i++]=overwrite;}a[i]=NULL;TestProc p=test_exec(a,NULL);int rc=p.code;test_proc_free(&p);return rc;}

